<?php
class CC_REST { public static function init(){add_action('rest_api_init',array(__CLASS__,'routes'));} public static function routes(){register_rest_route('cc/v1','/cities/(?P<id>\d+)/rating',array('methods'=>'GET','callback'=>array(__CLASS__,'get_rating'),'permission_callback'=>'__return_true')); register_rest_route('cc/v1','/cities/(?P<id>\d+)/rating',array('methods'=>'POST','callback'=>array(__CLASS__,'post_rating'),'permission_callback'=>function(){return is_user_logged_in() && wp_verify_nonce($_SERVER['HTTP_X_WP_NONCE']??'','wp_rest');})); register_rest_route('cc/v1','/submissions',array('methods'=>'POST','callback'=>array(__CLASS__,'submission'),'permission_callback'=>function(){return is_user_logged_in() && wp_verify_nonce($_SERVER['HTTP_X_WP_NONCE']??'','wp_rest');}));}
 public static function get_rating($r){$id=(int)$r['id']; if(get_post_type($id)!=='city')return new WP_Error('invalid_city','شهر معتبر نیست',array('status'=>404)); return CC_Rating::get($id);}
 public static function post_rating($r){global $wpdb; $id=(int)$r['id']; $stars=filter_var($r->get_param('stars'),FILTER_VALIDATE_INT); if(get_post_type($id)!=='city')return new WP_Error('invalid_city','شهر معتبر نیست',array('status'=>404)); if($stars<1||$stars>7)return new WP_Error('invalid_stars','امتیاز باید بین ۱ تا ۷ باشد',array('status'=>400)); $t=CC_DB::table(); $exists=$wpdb->get_var($wpdb->prepare("SELECT id FROM $t WHERE user_id=%d AND city_id=%d",get_current_user_id(),$id)); if($exists)return new WP_Error('already_rated','شما قبلاً به این شهر امتیاز داده‌اید',array('status'=>409)); $ok=$wpdb->insert($t,array('user_id'=>get_current_user_id(),'city_id'=>$id,'stars'=>$stars,'created_at'=>current_time('mysql')),array('%d','%d','%d','%s')); if(!$ok)return new WP_Error('db_error','ثبت امتیاز انجام نشد',array('status'=>500)); CC_DB::recalc($id); return CC_Rating::get($id);}
 public static function submission($r){$city=absint($r->get_param('city_id')); if(get_post_type($city)!=='city')return new WP_Error('invalid_city','شهر معتبر نیست',array('status'=>404)); $type=sanitize_key($r->get_param('type')); $text=sanitize_textarea_field($r->get_param('text')); if(!$text)return new WP_Error('empty','متن مشارکت الزامی است',array('status'=>400)); $p=wp_insert_post(array('post_type'=>'cc_submission','post_status'=>'pending','post_title'=>wp_trim_words($text,8),'post_content'=>$text,'post_author'=>get_current_user_id(),'meta_input'=>array('cc_city_id'=>$city,'cc_type'=>$type)),true); return is_wp_error($p)?$p:array('success'=>true,'message'=>'مشارکت شما برای بررسی ارسال شد.'); }
}
